// Copies the compiled contract (ABI + creation bytecode) into web/contract.js for the admin page's
// browser deploy. Run after `forge build` whenever src/ changes:  node script/export-web-contract.mjs
import { readFileSync, writeFileSync } from "node:fs";

const artifact = JSON.parse(readFileSync("out/BurnSwapPFP.sol/BurnSwapPFP.json", "utf8"));
const source = [
  "// Generated by script/export-web-contract.mjs from the forge build. Do not edit by hand.",
  `export const abi = ${JSON.stringify(artifact.abi)};`,
  `export const bytecode = "${artifact.bytecode.object}";`,
  "",
].join("\n");
writeFileSync("web/contract.js", source);
console.log(`web/contract.js: ${artifact.abi.length} ABI entries, ${(artifact.bytecode.object.length - 2) / 2} bytes of bytecode`);
